WITH flattened_attrs AS (SELECT id, created_at, ship_to, attributes, AGGREGATE(items, 0.0D, (acc, x) -> acc + x.qty * x.price, acc -> ROUND(acc, 2)) AS items_total, COALESCE(ship_to.country, 'UNKNOWN') AS country_or_unknown, SIZE(FILTER(items, x -> x.qty >= 3)) AS bulk_lines, ARRAY_CONTAINS(MAP_KEYS(attributes), 'weight_kg') AS has_weight_kg FROM carts WHERE created_at < '2024-05-12') SELECT CASE WHEN bulk_lines >= 3 THEN 'LARGE' ELSE 'SMALL' END AS bulk_lines_tier, PERCENTILE_APPROX(bulk_lines, 0.5) AS bulk_lines_p50, SUM(items_total) AS total_items_total, APPROX_PERCENTILE(items_total, ARRAY(0.25, 0.5, 0.75)) AS items_total_quartiles FROM flattened_attrs GROUP BY CASE WHEN bulk_lines >= 3 THEN 'LARGE' ELSE 'SMALL' END HAVING PERCENTILE_APPROX(bulk_lines, 0.5) > 0 ORDER BY bulk_lines_p50 DESC NULLS FIRST;
